export function getLocationServiceEntity(zipSlug: string, serviceSlug: string): LocationServiceEntity | undefined {
  return locationServiceData[`${zipSlug}/${serviceSlug}`];
}

export function getAllLocationServiceParams(): Array<{ zip: string; service: string }> {
  return Object.values(locationServiceData).map(e => ({
    zip: e.zipSlug,
    service: e.serviceSlug,
  }));
}